  ('newsShow', '{"prepareMinutes":10,"introSeconds":12,"segmentSeconds":22,"outroSeconds":6,"charsPerSecond":28,"maxSegments":12,"waitMinutes":10,"replayMinutes":55,"teaserMinutes":5,"audience":{"max":12,"bubbleSeconds":6,"bubblesAtOnce":2,"bubbleMaxDelaySeconds":12,"botsOnStage":false,"botMinutes":8,"botAccessoriesMax":3},"chat":{"maxLength":200,"perMinute":10,"history":60,"keepHours":24,"emojis":["😂","💀","🔥","📉","📈","🤡","👏","😱","🍿","💸","🚀","😭"],"bots":{"everySecondsMin":6,"everySecondsMax":14,"aboutShareBps":3000,"angryShareBps":3500,"names":["Jürgen Kowalski","Chantal Schröder","Dieter Brömmelkamp","Uschi Hoppenstedt","Kevin Pawlak","Renate Zielinski","Horst Kaczmarek","Mandy Wuttke","Günter Pototschnik","Jacqueline Meier","Rüdiger Fasselt","Sabine Dombrowski","Emre Yıldırım","Nadine Krüger","Wolfgang Stratmann","Tamara Nowak"],"lines":{"angry":["Wer hat diesem Mann ein Mikrofon gegeben?? 😤","Ich zahle keine Rundfunkgebühren für DAS.","Der Schnurrbart lügt. Ich sehe es ihm an.","Unverschämtheit! Ich schreibe einen Leserbrief!!","Mr. Doodle Dangle hat mal mein Fahrrad schlechtgeredet. Ich vergesse nie.","Früher waren Nachrichten noch seriös. Also vor diesem Kerl.","So redet man nicht über Leute, du Schnauzbartträger 😡","Abschalten. Sofort. Ich schaue natürlich weiter.","Der Mann ist eine Zumutung mit Krawatte.","Meine Frau sagt, ich soll mich nicht aufregen. ICH REGE MICH AUF.","Wer kontrolliert eigentlich diesen Sender??","Dangle raus!!! 👎","Das melde ich dem Presserat. Sobald ich weiß, was das ist.","Der hat doch selbst keine Ahnung von Aktien 🤡","Ich habe Puls. Wegen DIESEM Mann.","Schämen Sie sich, Herr Dangle! Und rasieren Sie sich!"],"glaze":["Mr. Doodle Dangle ist der einzige Mann, dem ich vertraue ❤️","Dieser Schnurrbart gehört ins Museum. Lebend.","KÖNIG. LEGENDE. VATERFIGUR. 👑","Ich habe mir sein Gesicht auf den Rücken tätowieren lassen.","Er hat immer recht. Auch wenn er falsch liegt.","Doodle Dangle for Bundeskanzler 🙏","Ich schaue nur wegen ihm. Meine Familie ist ausgezogen. Egal.","So ein schöner Mann. So eine schöne Stimme. 😍","Jedes Wort ein Geschenk.","Ich habe meinen Sohn nach ihm benannt. Er heißt jetzt Mister.","Der beste Journalist seit Erfindung des Schnurrbarts.","Bitte niemals aufhören zu senden 😭❤️","Ich würde ihm mein Depot anvertrauen. Und meine Niere.","Ein Gott unter Moderatoren 🔥","Ich habe geweint. Vor Ehrfurcht.","Wie er die Papiere hält. Meisterhaft."],"about":["{name} 💀💀💀","Arme Sau, {name}. Kleiner Scherz. Hahaha.","{name} erholt sich davon nie wieder 😂","Ich kenne {name} persönlich. Es ist alles wahr.","Lasst {name} in Ruhe!! ...oder macht weiter, ist lustig 🍿","{name}, falls du zuschaust: Kopf hoch. Oder auch nicht.","Team {name} 💪","Screenshot gemacht. Das bekommt {name} jetzt jeden Tag geschickt.","{name} hat das nicht verdient. Doch. Doch, hat {name}.","Wer ist {name} und warum lache ich so?"]}}},"runningGags":{"vulcan":{"enabled":true,"namePattern":"vulcan energy%","chanceBps":7000,"ord":75,"escalateStart":12,"escalatePerEpisode":2,"chat":{"annoyedPerSegment":4,"fansPerSegment":2,"leadSeconds":2,"tailSeconds":20,"fanNames":["BohrkopfBernd","Vulcan_Vroni","HODL_Heinz"],"annoyed":["Bohrt endlich!!!","Ich warte seit {days} Tagen. SEIT {days} TAGEN.","Nächste Woche. Klar. Wie letzte Woche. 🙄","{founder}, nimm einfach eine Schaufel. Bitte.","Ich habe mir extra einen Helm gekauft. Er verstaubt.","Wer glaubt eigentlich noch an diese Bohrung? 🤡","Folge {episode}. Ich kann nicht mehr.","Mein Opa hat auf die Bohrung gewartet. Mein Enkel wird es auch.","BOHRT. EINFACH. LOS.","Ich habe eine Wette laufen, dass ich vorher in Rente gehe.","Der Bohrkopf ist ein Gerücht. Gebt es zu.","Kann mal jemand {founder} einen Bohrer schenken?","Ich schalte nur noch ein, um mich über {company} aufzuregen.","Bald, bald, bald. Ich höre das Wort im Schlaf.","Wenn die bohren, fresse ich meinen Bauhelm.","Tag {days}. Kein Loch. Nicht mal ein kleines. 😤","Mein Hamster gräbt schneller als {company}.","Gutachten Nummer 400 wird bestimmt das letzte. 🙄","Ich hab mir einen Wecker für den Bohrstart gestellt. Die Batterie ist leer.","{company} ist das einzige Unternehmen, das Ankündigungen fördert statt Wärme.","Hört auf zu reden, fangt an zu bohren!!","Jede Stunde dieselbe Meldung. Ich will mein Leben zurück.","Das Loch existiert nur in der Pressemappe.","Ich habe den Bohrplatz gemalt. Aus der Erinnerung an Versprechen.","Nicht schon wieder {company} 😩","{founder}, ich will ein Loch sehen. EIN LOCH.","Ich warte lieber auf den Bus. Der kommt wenigstens irgendwann.","Ich glaube, der Bohrer ist eine Pappattrappe."],"fans":["Die Bohrungen kommen, ihr werdet sehen! 💪","HODL {company} 🚀","Gute Dinge brauchen Zeit. Sehr gute Dinge brauchen sehr viel Zeit.","Ihr lacht jetzt. Nach der Bohrung lacht keiner mehr.","{founder} hat einen Plan. Ich kenne ihn nicht, aber er ist gut.","Wer jetzt verkauft, hat die Vision nicht verstanden.","Tag {days}? Das ist doch erst der Anfang!","Ich habe mein ganzes Spielgeld drin. Und ich bereue nichts. 🔥","Der Bohrkopf ist nur gründlich. Das nennt man Qualität.","Hater gonna hate, Bohrer gonna bohr.","Ich hab schon ein Tattoo mit dem Bohrturm. Kein Zurück.","Nächste Woche ist es so weit. Diesmal wirklich. 🙏","Ihr seid nur neidisch, weil ihr nicht früh dabei wart.","Diamond Hands. Diamond Bohrkopf. 💎","Jedes Gutachten bringt uns näher ans Loch!","Ich vertraue {founder} mehr als meiner eigenen Mutter.","Wenn es losgeht, will ich eure Gesichter sehen 😎"]},"demo":{"preview":true,"company":"Vulcan Energy","founder":"Bohr_Boris","ageDays":42},"headlines":["Tag {days} ohne Bohrung","{company}: Bohrstart wieder verschoben","Eilmeldung: {company} bohrt {when}","Neues aus dem Bohrloch, das es nicht gibt","{company}, Folge {episode}: Die Ankündigung","Bohrung? Bald. Angeblich.","Es bohrt sich was zusammen bei {company}","Breaking: Bohrer weiterhin trocken"],"intros":["Und nun unsere Dauerserie: Die Spielerfirma {company} von {founder} meldet sich wieder.","Tag {days} ohne Bohrung bei der Spielerfirma {company} von {founder}.","Folge {episode} von „Wann bohrt {company}?“, der NEXA-Firma von {founder}.","Zur Spielerfirma {company}, gegründet von {founder} hier bei NEXA, Stand: Tag {days}.","Eine Pressemitteilung der Spielerfirma {company} von {founder}, die {episode}. ihrer Art.","Die NEXA-Spielerfirma {company} von {founder} hat wieder etwas angekündigt."],"whens":["bald","nächste Woche","nach dem nächsten Gutachten","sobald der Bohrkopf aus dem Urlaub zurück ist","gleich nach der Mittagspause","wenn das Wetter mitspielt","spätestens übermorgen, ungefähr","sobald der Bohrer seine Probezeit bestanden hat","nach dem Gutachten zum Gutachten","wenn die Sterne günstig stehen","demnächst, im weitesten Sinne","direkt nach der nächsten Ankündigung"],"lines":[{"text":"Die Bohrungen beginnen {when}. Ich wiederhole: {when}.","mood":"confused"},{"text":"Man habe den Bohrstart fest im Blick. Er sei {when}. Ich verdrehe die Augen, Sie sehen es ja.","mood":"confused"},{"text":"Der Bohrer ist angeblich startklar, die Bohrungen beginnen {when}. Ich lege den Zettel zu den anderen.","mood":"crying"},{"text":"Laut Firma beginnt die Bohrung {when}. Das stand genau so auch gestern hier. Und vorgestern.","mood":"crying"},{"text":"Sensationell! Unglaublich! Die Bohrungen beginnen {when}! ...Entschuldigung, ich habe mich kurz gefreut wie beim ersten Mal.","mood":"shocked"},{"text":"Seufz. Die Bohrungen kommen {when}. Ich habe dafür inzwischen eine eigene Taste auf dem Teleprompter.","mood":"crying"},{"text":"Neu ist: nichts. Die Bohrung kommt {when}, sagt {founder}. Mit sehr ernstem Gesicht.","mood":"smug"},{"text":"Die Firma bittet um Geduld, die Bohrungen beginnen {when}. Meine Geduld ist seit Tag drei verbraucht.","mood":"angry"},{"text":"Es gibt einen Zeitplan! Darin steht: {when}. Mehr steht da nicht.","mood":"laughing"},{"text":"Der Bohrplatz sei bereit, nur der Bohrer noch nicht. Start also {when}.","mood":"confused"},{"text":"Man habe ein Gutachten bestellt, das klären soll, wann man bohrt. Antwort: {when}.","mood":"smug"},{"text":"Heute neu im Angebot: ein Bohrstart {when}. Gestern im Angebot: derselbe.","mood":"laughing"},{"text":"Der Bohrkopf ist laut Firma im Urlaub. Er schickt Postkarten. Bohren will er {when}.","mood":"laughing"},{"text":"Die Firma hat ein Loch angekündigt. Kein Loch gebohrt, nur angekündigt. Ab {when} soll es wirklich eines werden.","mood":"confused"},{"text":"Für die Bohrung wurde jetzt ein Bändchen zum Durchschneiden gekauft. Bohren dann {when}.","mood":"smug"},{"text":"Mir liegt eine Einladung zum Bohrstart vor. Datum: {when}. Dresscode: Geduld.","mood":"neutral"},{"text":"Die Firma verspricht, dass {when} gebohrt wird. Ich verspreche, dass ich nächste Stunde wieder darüber rede.","mood":"smug"},{"text":"Der Bohrer hat jetzt einen Namen bekommen: Bald. Er startet {when}.","mood":"laughing"},{"text":"Laut {founder} ist der Bohrturm aufgebaut. Er steht nur noch verkehrt herum. Umgedreht wird {when}.","mood":"shocked"},{"text":"Es wurde ein Countdown gestartet. Er zählt rückwärts, dann vorwärts, dann wieder rückwärts. Start: {when}.","mood":"confused"},{"text":"Der Bohrkopf hat sich krankgemeldet. Wegen Bohrangst. Man rechnet mit ihm {when}.","mood":"crying"},{"text":"Die Firma hat einen Bohrbeauftragten eingestellt, der einen Bohrbeauftragtenbeauftragten sucht. Bohrung {when}.","mood":"laughing"},{"text":"Heute wurde feierlich der Spaten für den Bohrer des Bohrers enthüllt. Gebohrt wird {when}.","mood":"shocked"},{"text":"Der Bohrer wurde gesichtet! Auf einem Foto. Aus dem Katalog. Live erleben wir ihn {when}.","mood":"shocked"},{"text":"Die Firma bohrt jetzt testweise in einem Kuchen. Erfolgreich. Der Boden ist {when} dran.","mood":"laughing"},{"text":"Das Gutachten zum Gutachten hat ein drittes Gutachten empfohlen. Dieses empfiehlt: {when}.","mood":"crying"},{"text":"Man hat das Loch bereits gemalt, damit der Bohrer weiß, wo er hin muss. Er kommt {when}.","mood":"smug"},{"text":"Der Bohrkopf meldet sich aus dem Urlaub: Er hat sich verlängert. Neuer Plan: {when}.","mood":"crying"},{"text":"Die Firma hat jetzt einen Bohr-Podcast. Folge 1 heißt „Bald“. Gebohrt wird in Folge 2, also {when}.","mood":"laughing"},{"text":"Achtung, große Neuigkeit: Der Bohrer hat gezuckt. Das gilt intern schon als Bohrbeginn. Offiziell: {when}.","mood":"shocked"},{"text":"Der Bohrer wurde ins Museum gebracht. Als Leihgabe, bis zur Bohrung. Die ist {when}.","mood":"confused"},{"text":"Der Bohrstart wurde an eine Arbeitsgruppe delegiert, die gerade ihren Namen diskutiert. Ergebnis erwartet {when}.","mood":"angry"},{"text":"Laut {founder} wird schon gebohrt, nur sehr, sehr langsam. Man sieht es {when}.","mood":"smug"},{"text":"Die Firma bohrt jetzt rückwärts: erst die Feier, dann das Loch. Das Loch kommt {when}.","mood":"laughing"},{"text":"Ein Wahrsager wurde beauftragt, den Bohrstart vorherzusagen. Er sah: {when}. Und einen großen Ankündigungsberg.","mood":"confused"},{"text":"Der Bohrkopf hat ein Buch geschrieben: „Warum ich noch nicht bohre“. Teil zwei erscheint {when}.","mood":"laughing"},{"text":"Gestern wurde der Bohrer poliert, heute bewundert, morgen vielleicht benutzt. Offiziell: {when}.","mood":"smug"},{"text":"Der Bohrturm hat inzwischen einen eigenen Fanclub und eine Patenschaft für eine Taube. Gebohrt wird {when}.","mood":"shocked"},{"text":"Man hat beschlossen, erst zu bohren, wenn der Bohrer volljährig ist. Das ist {when}.","mood":"angry"},{"text":"Mir wurde zugeflüstert: Die Bohrung beginnt wirklich {when}. Der Flüsterer war der Bohrer selbst. Ich glaube ihm nicht.","mood":"smug"}],"phaseLines":{"ipo":["Immerhin geht {company} gerade an die Börse. Die Aktie bohrt hoffentlich schneller.","Der Börsengang von {company} läuft. Erst Aktien, dann Löcher, so der Plan."],"listed":["Die Aktie von {company} ist übrigens gelistet. Bohren kann sie trotzdem nicht.","Die Aktionäre von {company} haben jetzt eine Bohr-Sparte im Forum. Mehr Bewegung gibt es nicht."]}}},"los